-- RLS for kon-agile after the English rename: functions, triggers and policies come back with the new names.
--
-- The previous file dropped the old ones; between both files the tables stay closed, not open.

-- Functions: their bodies are text, so a rename does not reach them.
CREATE OR REPLACE FUNCTION agile_issue_project(i uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT project_id FROM agile_issues WHERE id = i
$function$;

CREATE OR REPLACE FUNCTION agile_project_role(p uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT CASE
        WHEN EXISTS (SELECT 1 FROM agile_projects
                     WHERE id = p
                       AND created_by = current_setting('app.current_user_id', true))
            THEN 'owner'
        ELSE (SELECT role FROM agile_project_members
              WHERE project_id = p
                AND user_id = current_setting('app.current_user_id', true))
    END
$function$;

-- Policies, with the new names and the core's English helpers.
DROP POLICY IF EXISTS agile_activity_log_agile_insert ON agile_activity_log;
CREATE POLICY agile_activity_log_agile_insert ON agile_activity_log AS PERMISSIVE FOR INSERT WITH CHECK ((((COALESCE(current_setting('app.current_user_id'::text, true), ''::text) = ''::text) AND (COALESCE(current_setting('app.current_user_role'::text, true), ''::text) = ''::text)) OR (current_setting('app.current_user_role'::text, true) = 'admin'::text) OR (agile_project_role(project_id) = ANY (ARRAY['owner'::text, 'member'::text]))));
